def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    marker = next((v for row in grid for v in row if v != grid[0][0]), None)
    if marker is None:
        return out

    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    for i, (r1, c1) in enumerate(points):
        for r2, c2 in points[i + 1:]:
            if r1 == r2:
                for c in range(min(c1, c2) + 1, max(c1, c2)):
                    if grid[r1][c] != marker:
                        out[r1][c] = 3
            elif c1 == c2:
                for r in range(min(r1, r2) + 1, max(r1, r2)):
                    if grid[r][c1] != marker:
                        out[r][c1] = 3
    return out
